asc.toList(asc.size()).getInfo().forEach(function(imageInfo) {
var image = ee.Image(imageInfo.id).select(['VV', 'angle']); // VV 및 angle 밴드
선택
var normalizedImage = sigma0Normalization(image, 30); // Sigma0 정규화 수행
var naturalImage = toNatural(normalizedImage.select('VV_sigma0_normalized'));
// dB에서 자연 단위로 변환
var filteredImage = refinedLee(naturalImage); // Refined Lee 필터 적용
var dbImage = toDB(filteredImage); // 다시 dB로 변환
var description = 'ASC\_' + imageInfo.id.split('/').pop();
exportImage(dbImage, description); // 정규화된 밴드 내보내기});
